/*
 * GA2 shared helpers for the ga2_* sources (Top Spin 4, Xbox 360, Swing_DLL.xex, gameplay code
 * 0x886601F0..0x8867B608). Structs list only the fields the matched functions touch; the rest is
 * padding generated by PAD(n). Field names state a role when the access pattern shows one,
 * otherwise only the offset (f_XXXX).
 */
#ifndef GA2_TYPES_H
#define GA2_TYPES_H

typedef unsigned char ga2_u8;
typedef unsigned short ga2_u16;
typedef unsigned int ga2_u32;

#define GA2_CAT2(a, b) a##b
#define GA2_CAT(a, b) GA2_CAT2(a, b)
#define PAD(n) ga2_u8 GA2_CAT(pad_, __COUNTER__)[n]

#endif
